def require(condition, message):
    if not condition:
        raise ValueError(message)

def one(pattern, text):
    matches = re.findall(pattern, text, re.M)
    require(len(matches) == 1, f'expected one {pattern!r}; got {len(matches)}')
    return matches[0]

def stats(a, b):
    require(len(a) == len(b) == 3, 'three complete pairs required')
    ma, mb = st.median(a), st.median(b)
    return dict(pairs=3, baseline_median_us=ma, combined_median_us=mb,
                baseline_mean_us=st.mean(a), combined_mean_us=st.mean(b),
                ratio=mb / ma if ma else None,
                baseline_min_us=min(a), baseline_max_us=max(a),
                combined_min_us=min(b), combined_max_us=max(b),
                faster_pairs=sum(y < x for x, y in zip(a, b)),
                slower_pairs=sum(y > x for x, y in zip(a, b)),
                direction='lower observed range' if max(b) < min(a) else
                          'higher observed range' if min(b) > max(a) else 'overlapping ranges',
                baseline_pair0_us=a[0], combined_pair0_us=b[0],
                baseline_pair1_us=a[1], combined_pair1_us=b[1],
                baseline_pair2_us=a[2], combined_pair2_us=b[2])

def tap(log, plan, todo_names=frozenset(), skip_names=frozenset(), todo_passes=frozenset()):
    require(int(one(r'^1\.\.(\d+)\s*$', log)) == plan, 'wrong TAP plan')
    require(not re.search(r'^\s*Bail out!', log, re.M), 'TAP bailout')
    rows = re.findall(r'^(not ok|ok) (\d+) - (.+)$', log, re.M)
    require(len(re.findall(r'^(?:not ok|ok)\b.*$', log, re.M)) == len(rows), 'malformed TAP record')
    require(len(rows) == plan and [int(x[1]) for x in rows] == list(range(1, plan + 1)),
            'missing, duplicate, or unordered TAP checks')
    actual_todo, actual_skip, ordinary = set(), set(), []
    for status, number, description in rows:
        name = description.split(' # ')[0]
        if ' # TODO ' in description:
            require(status == ('ok' if name in todo_passes else 'not ok'), f'unexpected TODO disposition {name}')
            actual_todo.add(name)
        elif ' # SKIP ' in description:
            require(status == 'ok', f'failed SKIP {name}')
            actual_skip.add(name)
        else:
            require(status == 'ok', f'failed check {number}: {description}')
            ordinary.append(name)
    require(actual_todo == set(todo_names), f'TODO mismatch {actual_todo}')
    require(actual_skip == set(skip_names), f'SKIP mismatch {actual_skip}')
    return ordinary

def parse_micro(log):
    passing = tap(log, 41)
    require(one(r'^== kernel-performance-portable end (\w+) ==$', log) == 'PASS', 'micro terminal')
    require(one(r'^# PERF-SUMMARY workloads=(\d+) failures=(\d+)$', log) == ('40', '0'), 'micro summary')
    frequency, samples = one(r'^# PERF-META version=1 clock=KeQueryPerformanceCounter frequency=(\d+) samples=(\d+)$', log)
    require(int(frequency) > 0 and samples == '3', 'micro metadata')
    entries = re.findall(r'^# PERF workload=(\S+) sample=(\d+) iterations=(\d+) ticks=(\d+) correct=(\d+) checksum=(\S+)$', log, re.M)
    require(len(entries) == 118 and len(re.findall(r'^# PERF .*$',log,re.M)) == 118, 'micro sample count mismatch')
    got, values = {}, {}
    for name, sample, iterations, ticks, correct, checksum in entries:
        key = name + '/' + sample
        require(key not in got and correct == '1' and int(iterations) > 0, 'duplicate/invalid micro sample')
        got[key] = [int(iterations), checksum]
        values.setdefault(name, []).append(int(ticks) * 1e6 / int(frequency) / int(iterations))
    require(got == EXPECTED_MICRO, 'micro iteration/sample/checksum contract mismatch')
    require(len(values) == 40 and set(passing) == set(values) | {'public-known-answers'}, 'micro workload set')
    return {name: st.median(samples) for name, samples in values.items()}

def parse_stream(log):
    tap(log, 1034)
    require(one(r'^# checks=(\d+) failures=(\d+)$', log) == ('1034', '0'), 'stream summary')
    entries = re.findall(r'^# stream phase=(\d+) pages=(\d+) reads=(\d+) pending=(\d+) elapsed_ms=(\d+) submit_us_total=(\d+) p50=(\d+) p95=(\d+) max=(\d+) completion_us_total=(\d+) p50=(\d+) p95=(\d+) max=(\d+).*$', log, re.M)
    require(len(entries) == 2 and len(re.findall(r'^# stream .*$',log,re.M)) == 2 and [r[0] for r in entries] == ['0', '1'], 'stream phases incomplete')
    values = {}
    for row in entries:
        phase, pages, reads, pending, elapsed, submit, sp50, sp95, smax, completion, cp50, cp95, cmax = map(int, row)
        require(reads == 1024 and 0 <= pending <= reads, 'stream read/pending contract')
        require((pages > 1024 if phase == 0 else 0 < pages <= 1024), 'stream pressure contract')
        require(sp50 <= sp95 <= smax and cp50 <= cp95 <= cmax, 'stream percentile order')
        for name, value in [('elapsed', elapsed * 1000), ('submit_total', submit), ('submit_p50', sp50),
                            ('submit_p95', sp95), ('submit_max', smax), ('completion_total', completion),
                            ('completion_p50', cp50), ('completion_p95', cp95), ('completion_max', cmax)]:
            values[f'phase{phase}/{name}'] = value
    states = re.findall(r'^# submission state: completed_iosb_at_return=(\d+) short_reads=(\d+) short_submit_us=(\d+) long_reads=(\d+) long_submit_us=(\d+)$', log, re.M)
    require(len(states) == 2, 'stream submission-state count')
    for completed, short, stime, long, ltime in states:
        require(int(completed) <= 1024 and (short, long) == ('547', '477'), 'stream completed/size mix')
    return values

def parse_sync(log):
    tap(log, 36)
    require(one(r'^# checks=(\d+) failures=(\d+)$', log) == ('36', '0'), 'sync summary')
    entries = re.findall(r'^# sync mode=(\d+) sample=(\d+) count=(\d+) ticks=(\d+) us=(\d+) successes=(\d+)$', log, re.M)
    require(len(entries) == 32 and len(re.findall(r'^# sync .*$',log,re.M)) == 32, 'sync sample count')
    values, seen = {}, set()
    for mode, sample, count, ticks, us, successes in entries:
        key = int(mode), int(sample)
        require(key not in seen and count == successes == '32768', 'sync count/duplicate mismatch')
        seen.add(key)
        values.setdefault(mode, []).append(int(us) / int(count))
    require(seen == {(m, s) for m in range(4) for s in range(8)}, 'sync modes/sample set')
    return {f'mode{mode}': st.median(samples) for mode, samples in values.items()}

def parse_apc(log):
    tap(log, 30)
    require(one(r'^# checks=(\d+) failures=(\d+)$', log) == ('30', '0'), 'focused summary')
    rows = re.findall(r'^# mode=(\d+) alertable=(\d+) cancel=(\d+) status=([0-9a-f]+) elapsed=(\d+) callbacks=(\d+)$', log, re.M)
    require(len(rows) == 4 and len(re.findall(r'^# mode=.*$',log,re.M)) == 4, 'focused diagnostic count')
    contracts = [('1', '1', '0', '000000c0', '1'), ('1', '0', '0', '00000102', '0'),
                 ('1', '0', '1', '00000102', '0'), ('0', '1', '0', '00000102', '1')]
    require([(m, a, c, status, calls) for m, a, c, status, elapsed, calls in rows] == contracts, 'focused APC contract mismatch')
    return {'checks': 30, 'failures': 0, 'user_alertable_elapsed_ms': int(rows[0][4]), 'timing_is_diagnostic_only': True}

def parse_storage(log):
    tap(log, 48)
    require(one(r'^# checks=(\d+) failures=(\d+)$', log) == ('48', '0'), 'storage summary mismatch')
    rows = re.findall(r'^# resize result (\S+) status=([0-9a-f]+) iosb=([0-9a-f]+) info=(\d+)$', log, re.M)
    require(len(re.findall(r'^# resize result .*$',log,re.M)) == 5, 'storage resize diagnostic count')
    require(rows == [(name, status, '5a5a5a5a', '1515870810') for name, status in
        [('exact-4GiB','c000007f'), ('4GiB-plus-512','c000007f'),
         ('beyond-free-large','c000007f'), ('negative-lowpart-512','c000000d'),
         ('beyond-free-small','c000007f')]], 'storage resize contract mismatch')
    for shape in ('readonly-volume', 'readonly-file'):
        require(one(r'^# flush '+shape+r' status=([0-9a-f]+) iosb=([0-9a-f]+) info=(\d+)$', log) ==
                ('00000000','00000000','0'), 'storage flush contract mismatch')
    free_high, free_low, cluster = map(int, one(r'^# large free units=(\d+):(\d+) cluster=(\d+)$', log))
    require(((free_high << 32) + free_low) * cluster > 0x100000200, 'storage cap-only volume too small')
    return {'checks':48, 'failures':0, 'preservation_checks':15}
